import {
  AppError,
  can,
  ensureMatchInput,
  isUser,
  operationSchema,
  PARENT_DELETED_DETAIL,
  validateEntryData,
  withinSelfEditWindow,
  validateEntryShape,
  type Caller,
  type ErrorCode,
  type Operation,
  type PushRequest,
  type PushResponse,
  type PushResult,
  type RejectionReason,
  type RobotStatus,
} from '@frc/shared';
import type { ZodIssue } from 'zod';
import type { StoredUser, UseCaseContext } from '../context.js';
import { pgCode } from '../seasonRows.js';
import { ensureMatch } from './matches.js';

const rejected = (opId: string, reason: RejectionReason, detail?: string): PushResult =>
  detail === undefined
    ? { op_id: opId, status: 'rejected', reason }
    : { op_id: opId, status: 'rejected', reason, detail };

/**
 * Keys the server owns or derives from the operation itself. They are dropped from the
 * payload before a write, so a client can neither reassign authorship, set its own
 * version, nor supply an `updated_at` that bypasses the `now()` default and hides the row
 * from the delta pull's cursor (SPEC-FINAL 9.3, 9.4).
 */
const SERVER_OWNED_KEYS = new Set([
  'id',
  'scouter_id',
  'version',
  'created_at',
  'updated_at',
  'deleted_at',
  'client_created_at',
  'client_updated_at',
]);

/**
 * A foreign-key failure (Postgres '23503') as the parent it names. Only the constraint name
 * is read, and only a fixed detail goes back: Postgres's own text never reaches the client.
 */
function foreignKeyDetail(message: string): string {
  const column = /_(event|match|team|form_version)_id_fkey/.exec(message)?.[1];
  return column
    ? PARENT_DELETED_DETAIL[column as keyof typeof PARENT_DELETED_DETAIL]
    : PARENT_DELETED_DETAIL.other;
}

const withoutServerOwnedKeys = (payload: Record<string, unknown>): Record<string, unknown> =>
  Object.fromEntries(Object.entries(payload).filter(([key]) => !SERVER_OWNED_KEYS.has(key)));

/**
 * The caller every capability check in this file reads: the operation's AUTHOR, never the
 * bearer (SPEC-FINAL 7.5). The bearer's role grants nothing.
 */
const callerOf = (author: StoredUser): Caller => ({
  kind: 'user',
  userId: author.id,
  role: author.role,
});

/** One zod issue as `path: message`, never with the value it was about. */
function describeIssue(issue: ZodIssue): string {
  const path = issue.path.join('.') || 'operation';
  // invalid_enum_value's own message quotes the value received; name the options instead.
  const message =
    issue.code === 'invalid_enum_value' ? `expected ${issue.options.join(' | ')}` : issue.message;
  return `${path}: ${message}`;
}

const opIdOf = (candidate: unknown): string | null => {
  if (typeof candidate !== 'object' || candidate === null) return null;
  const opId = (candidate as { op_id?: unknown }).op_id;
  return typeof opId === 'string' && opId.length > 0 ? opId : null;
};

/**
 * SPEC-FINAL 9.3.1 (UF.12): the route parses the push envelope strictly and each operation
 * here, on its own. A malformed operation is answered `invalid` with the fields it got
 * wrong, so it is parked on the device and shown, and every good operation in the batch
 * is still applied. One with no op_id cannot be answered at all, so it is skipped. Either
 * way the issue paths and codes are logged, keyed by op_id, never with a value.
 */
export function screenOperations(raw: unknown[]): {
  operations: Operation[];
  rejections: PushResult[];
} {
  const operations: Operation[] = [];
  const rejections: PushResult[] = [];
  raw.forEach((candidate, index) => {
    const parsed = operationSchema.safeParse(candidate);
    if (parsed.success) {
      operations.push(parsed.data);
      return;
    }
    const { issues } = parsed.error;
    const codes = issues.map((i) => `${i.path.join('.') || 'operation'} ${i.code}`).join(', ');
    const opId = opIdOf(candidate);
    if (opId === null) {
      console.error(`syncPush: skipped operation #${index}, which has no op_id: ${codes}`);
      return;
    }
    console.error(`syncPush: op ${opId} is malformed: ${codes}`);
    rejections.push(rejected(opId, 'invalid', issues.map(describeIssue).join('; ')));
  });
  return { operations, rejections };
}

/**
 * SPEC-FINAL 9.3.1. Operations are applied in seq order, each independently; a
 * rejection does not stop the batch. op_id is the idempotency key. Authorization is
 * per operation, against the operation's author_user_id and not against the bearer
 * (7.5) — which is what makes a shared collector tablet work at all.
 *
 * Divergence and duplicate arrive in task 1.40. Until then a stale base version is
 * rejected as `invalid` rather than silently overwriting. A missing parent is
 * `parent-deleted` with a PARENT_DELETED_DETAIL naming it (UF.1).
 */
export async function syncPush(
  caller: Caller,
  input: PushRequest,
  ctx: UseCaseContext,
): Promise<PushResponse> {
  const ordered = [...input.operations].sort((a, b) => a.seq - b.seq);
  const results: PushResult[] = [];

  for (const op of ordered) {
    try {
      results.push(await applyOne(caller, op, ctx));
    } catch (e) {
      // 9.3.1: one operation's failure never takes the batch down. The underlying
      // message is logged here, keyed by op_id and never with the payload, and NOT sent
      // back: a Postgres/PostgREST message can carry schema or row detail. (An opaque
      // 500 hid a schema bug once — the Vercel runtime log is where to look now.)
      const message = e instanceof Error ? e.message : String(e);
      console.error(`syncPush: op ${op.op_id} (${op.entity} ${op.action}) failed: ${message}`);
      // 9.3.1 (v1.18): a missing parent is ALWAYS parent-deleted. The checks in applyEntry
      // catch it first; this is a parent deleted between that check and the write. The
      // generic answer is left for what is genuinely unexpected, because the client
      // retries it silently for ever.
      results.push(
        pgCode(e) === '23503'
          ? rejected(op.op_id, 'parent-deleted', foreignKeyDetail(message))
          : rejected(op.op_id, 'invalid', 'unexpected server error'),
      );
    }
  }
  return { results };
}

async function applyOne(caller: Caller, op: Operation, ctx: UseCaseContext): Promise<PushResult> {
  if (!isUser(caller)) return rejected(op.op_id, 'forbidden', 'a service caller may not push');

  const author = await ctx.store.getUser(op.author_user_id);
  if (!author) return rejected(op.op_id, 'forbidden', 'unknown author');
  if (author.disabled_at !== null) return rejected(op.op_id, 'forbidden', 'the author is disabled');

  if (await ctx.store.wasApplied(op.op_id)) {
    // Matches are not versioned (SPEC-FINAL 6.4: event, type, number and nothing else).
    // The replay names the CANONICAL id, as the first answer did, so a device whose
    // first response was lost still learns which id the server kept.
    if (op.entity === 'match') {
      return {
        op_id: op.op_id,
        status: 'noop',
        row_id: await canonicalMatchId(op, ctx),
        new_version: 1,
      };
    }
    const existing = await ctx.store.getRow(op.entity, op.row_id);
    return {
      op_id: op.op_id,
      status: 'noop',
      row_id: op.row_id,
      new_version: existing?.version ?? 1,
    };
  }

  if (op.entity === 'match') return applyBareMatch(op, author, ctx);
  if (op.entity !== 'scouting_entry') {
    return rejected(op.op_id, 'invalid', `entity '${op.entity}' is not accepted yet`);
  }
  return applyEntry(op, author, ctx);
}

/**
 * The bare match fields of an operation, as ensureMatch takes them. `id` is the op's
 * row_id; everything else comes from the payload, and ensureMatch validates all of it.
 */
const bareMatchInput = (op: Operation) => {
  const { event_id, match_type, number } = op.payload as Record<string, unknown>;
  return { id: op.row_id, event_id, match_type, number } as Parameters<typeof ensureMatch>[1];
};

/** The id the server holds for this op's (event, type, number), else the op's own. */
async function canonicalMatchId(op: Operation, ctx: UseCaseContext): Promise<string> {
  const parsed = ensureMatchInput.safeParse(bareMatchInput(op));
  if (!parsed.success) return op.row_id;
  const { event_id, match_type, number } = parsed.data;
  return (await ctx.store.findMatch(event_id, match_type, number))?.id ?? op.row_id;
}

/**
 * A use case's refusal as a push rejection (SPEC-FINAL 9.3.1 has four reasons). A missing
 * event is `parent-deleted` — the parent of the row is gone (9.5), which is what the
 * client's 9.7 handling is for.
 */
const REASON_FOR: Partial<Record<ErrorCode, RejectionReason>> = {
  forbidden: 'forbidden',
  'not-found': 'parent-deleted',
  invalid: 'invalid',
};

/**
 * SPEC-FINAL 6.4: the bare auto-creation, through ensureMatch — the one implementation of
 * the rule. Its caller is the operation's AUTHOR, never the bearer (7.5), so ensureMatch's
 * own `ensure_match` check is this operation's authorization.
 *
 * When the match already exists the answer is `noop` with the EXISTING match's id, which
 * may differ from op.row_id: two offline devices can each auto-create the same match
 * number under their own ids, and the second must remap to the first's. `matches` has no
 * version column, so new_version is always 1.
 */
async function applyBareMatch(
  op: Operation,
  author: StoredUser,
  ctx: UseCaseContext,
): Promise<PushResult> {
  let result: { id: string; created: boolean };
  try {
    result = await ensureMatch(callerOf(author), bareMatchInput(op), ctx);
  } catch (e) {
    if (!(e instanceof AppError)) throw e;
    const reason = REASON_FOR[e.code] ?? 'invalid';
    // ensureMatch's only not-found is its event.
    const detail = reason === 'parent-deleted' ? PARENT_DELETED_DETAIL.event : e.message;
    return rejected(op.op_id, reason, detail);
  }
  await ctx.store.markApplied(op.op_id);
  return {
    op_id: op.op_id,
    status: result.created ? 'applied' : 'noop',
    row_id: result.id,
    new_version: 1,
  };
}

async function applyEntry(
  op: Operation,
  author: StoredUser,
  ctx: UseCaseContext,
): Promise<PushResult> {
  const payload = op.payload as Record<string, unknown>;
  const authorCaller = callerOf(author);
  const existing = await ctx.store.getRow('scouting_entry', op.row_id);

  if (op.action === 'delete') {
    // SPEC-FINAL 7.6: scouters never delete. Removal is a lead/admin soft-delete.
    if (!can(authorCaller, 'manage_entries')) {
      return rejected(op.op_id, 'forbidden', 'only a lead or admin may delete an entry');
    }
    if (!existing) return rejected(op.op_id, 'invalid', 'no such entry');
    await ctx.store.putRow('scouting_entry', op.row_id, {
      ...existing,
      deleted_at: ctx.now().toISOString(),
      version: existing.version + 1,
      client_updated_at: op.client_updated_at,
    });
    await ctx.store.markApplied(op.op_id);
    return {
      op_id: op.op_id,
      status: 'applied',
      row_id: op.row_id,
      new_version: existing.version + 1,
    };
  }

  if (existing) {
    // An edit of a row the server already holds. A lead or admin may manage any entry at
    // any age; anyone else only their own, inside the self-edit window (SPEC-FINAL 7.6).
    if (!can(authorCaller, 'manage_entries')) {
      if (existing.scouter_id !== author.id) {
        return rejected(op.op_id, 'forbidden', 'a scouter may edit only their own entry');
      }
      // The two CLIENT timestamps, compared to each other and never to server time. The
      // created stamp is the ROW's, not the operation's, so a client cannot widen its own
      // window by resending a fresher client_created_at.
      if (!withinSelfEditWindow(String(existing.client_created_at), op.client_updated_at)) {
        return rejected(op.op_id, 'edit-window-expired', 'this entry is locked — ask a lead');
      }
    }
  } else if (!can(authorCaller, 'submit_entry')) {
    return rejected(op.op_id, 'forbidden', 'the author may not submit an entry');
  }

  if (existing && op.base_version !== existing.version) {
    // Task 1.40 turns this into the divergence path of SPEC-FINAL 9.5.
    return rejected(op.op_id, 'invalid', `stale base version ${op.base_version}`);
  }

  const formVersionId = payload.form_version_id;
  if (typeof formVersionId !== 'string') {
    return rejected(op.op_id, 'invalid', 'form_version_id is required');
  }
  // SPEC-FINAL 3.5: the cross-column rules first, then the JSONB payload.
  const shapeIssues = validateEntryShape({
    form_kind: payload.form_kind as 'match' | 'super',
    match_id: (payload.match_id as string | null) ?? null,
    alliance: (payload.alliance as 'red' | 'blue' | null) ?? null,
    robot_status: (payload.robot_status as RobotStatus | null) ?? null,
    breakdown_seconds: (payload.breakdown_seconds as number | null) ?? null,
  });
  if (shapeIssues.length > 0) return rejected(op.op_id, 'invalid', shapeIssues.join('; '));

  // SPEC-FINAL 9.3.1 (v1.18): a missing parent is parent-deleted, named, before any write.
  // Without this the insert hit the foreign key and the client was told "unexpected server
  // error", which it retries silently for ever (UI-FIX-NOTES, Entry 4).
  const { event_id: eventId, match_id: matchId, team_id: teamId } = payload;
  if (typeof eventId !== 'string') return rejected(op.op_id, 'invalid', 'event_id is required');
  if (typeof teamId !== 'string') return rejected(op.op_id, 'invalid', 'team_id is required');
  if (matchId != null && typeof matchId !== 'string') {
    return rejected(op.op_id, 'invalid', 'match_id must be an id or null');
  }
  const gone = await ctx.store.missingParent({
    event_id: eventId,
    match_id: matchId ?? null,
    team_id: teamId,
  });
  if (gone !== null) return rejected(op.op_id, 'parent-deleted', PARENT_DELETED_DETAIL[gone]);

  const fields = await ctx.store.getFormFields(formVersionId);
  const status = (payload.robot_status as RobotStatus | null) ?? 'played';
  const data = (payload.data ?? {}) as Record<string, unknown>;
  // 'stored', not 'submit': the version's config, ranges, required flags and event types may
  // have been edited in place since the device collected this entry, and an in-place edit
  // never invalidates collected data (SPEC-FINAL 5.1, 15.1). The device ran 'submit' itself.
  const validation = validateEntryData(fields, status, data, { mode: 'stored' });
  if (!validation.ok) {
    return rejected(op.op_id, 'invalid', validation.issues.map((i) => i.message).join('; '));
  }

  const version = existing ? existing.version + 1 : 1;
  await ctx.store.putRow('scouting_entry', op.row_id, {
    ...withoutServerOwnedKeys(payload),
    id: op.row_id,
    // An update never reassigns authorship, and never restarts the self-edit window: both
    // stay the row's own (SPEC-FINAL 7.5, 7.6). A create takes them from the operation.
    scouter_id: existing ? existing.scouter_id : op.author_user_id,
    version,
    client_created_at: existing ? existing.client_created_at : op.client_created_at,
    client_updated_at: op.client_updated_at,
    deleted_at: null,
  });
  await ctx.store.markApplied(op.op_id);
  return { op_id: op.op_id, status: 'applied', row_id: op.row_id, new_version: version };
}
